    @Override // android.app.Activity
    protected void onActivityResult(int requestCode, int resultCode, Intent data) {
        super.onActivityResult(requestCode, resultCode, data);
        if (requestCode == this.REQUEST_CODE_CHOOSE_IMAGE) {
            if (resultCode == -1) {
                this.isNewImageGet = true;
                this.mIntent = data;
                return;
            } else {
                this.isNewImageGet = false;
                return;
            }
        }
        if (requestCode == this.REQUEST_CODE_SETTING && data != null) {
            boolean audioModified = data.getExtras().getBoolean(Constants.KEY_PREFERENCES_AUDIO_SETTING_MODIFIED);
            if (audioModified) {
                initStateFromPreferencesSetting();
                if (this.isMusicOn) {
                    this.mPlayer.start();
                } else if (!this.isMusicOn) {
                    this.mPlayer.pause();
                }
            }
            boolean levelModified = data.getExtras().getBoolean(Constants.KEY_PREFERENCES_LEVEL_SETTING_MODIFIED);
            if (levelModified) {
                initStateFromPreferencesSetting();
                initGame();
            }
        }
    }

